   188→  if (dataColumnSidecar.index >= NUMBER_OF_COLUMNS) {
   189→    throw new DataColumnSidecarGossipError(GossipAction.REJECT, {
   190→      code: DataColumnSidecarErrorCode.INVALID_INDEX,
   191→      slot: dataColumnSidecar.signedBlockHeader.message.slot,
   192→      columnIdx: dataColumnSidecar.index,
   193→    });
   194→  }
   195→
   196→  if (dataColumnSidecar.kzgCommitments.length === 0) {
   197→    throw new DataColumnSidecarGossipError(GossipAction.REJECT, {
   198→      code: DataColumnSidecarErrorCode.NO_COMMITMENTS,
   199→      slot: dataColumnSidecar.signedBlockHeader.message.slot,
   200→      columnIdx: dataColumnSidecar.index,
   201→    });
   202→  }
   203→
   204→  if (
   205→    dataColumnSidecar.column.length !== dataColumnSidecar.kzgCommitments.length ||
   206→    dataColumnSidecar.column.length !== dataColumnSidecar.kzgProofs.length
   207→  ) {
   208→    throw new DataColumnSidecarGossipError(GossipAction.REJECT, {
   209→      code: DataColumnSidecarErrorCode.MISMATCHED_LENGTHS,
   210→      columnLength: dataColumnSidecar.column.length,
   211→      commitmentsLength: dataColumnSidecar.kzgCommitments.length,
   212→      proofsLength: dataColumnSidecar.kzgProofs.length,
   213→    });
   214→  }
   215→}
   216→
   217→/**
   218→ * SPEC FUNCTION
   219→ * https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/fulu/p2p-interface.md#verify_data_column_sidecar_kzg_proofs
   220→ */
   221→export async function verifyDataColumnSidecarKzgProofs(
   222→  commitments: Uint8Array[],
   223→  cellIndices: number[],
   224→  cells: Uint8Array[],
   225→  proofs: Uint8Array[]
   226→): Promise<void> {
   227→  let valid: boolean;
   228→  try {
   229→    valid = await kzg.asyncVerifyCellKzgProofBatch(commitments, cellIndices, cells, proofs);
   230→  } catch (e) {
   231→    (e as Error).message = `Error on asyncVerifyCellKzgProofBatch: ${(e as Error).message}`;
   232→    throw e;
   233→  }
   234→  if (!valid) {
   235→    throw Error("Invalid verifyCellKzgProofBatch");
   236→  }
   237→}
   238→
   239→/**
   240→ * SPEC FUNCTION
   241→ * https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/fulu/p2p-interface.md#verify_data_column_sidecar_inclusion_proof
   242→ */
   243→export function verifyDataColumnSidecarInclusionProof(dataColumnSidecar: fulu.DataColumnSidecar): boolean {
   244→  return verifyMerkleBranch(
   245→    ssz.deneb.BlobKzgCommitments.hashTreeRoot(dataColumnSidecar.kzgCommitments),
   246→    dataColumnSidecar.kzgCommitmentsInclusionProof,
   247→    KZG_COMMITMENTS_INCLUSION_PROOF_DEPTH,
   248→    KZG_COMMITMENTS_SUBTREE_INDEX,
   249→    dataColumnSidecar.signedBlockHeader.message.bodyRoot
   250→  );
   251→}
   252→
   253→/**
   254→ * Validate a subset of data column sidecars in a block
   255→ *
   256→ * Requires the block to be known to the node
   257→ */
   258→export async function validateBlockDataColumnSidecars(
   259→  blockSlot: Slot,
   260→  blockRoot: Root,
   261→  blockBlobCount: number,
   262→  dataColumnSidecars: fulu.DataColumnSidecars
   263→): Promise<void> {
   264→  if (dataColumnSidecars.length === 0) {
   265→    return;
   266→  }
   267→
   268→  if (blockBlobCount === 0) {
   269→    throw new DataColumnSidecarValidationError(
   270→      {
   271→        code: DataColumnSidecarErrorCode.INCORRECT_SIDECAR_COUNT,
   272→        slot: blockSlot,
   273→        expected: 0,
   274→        actual: dataColumnSidecars.length,
   275→      },
   276→      "Block has no blob commitments but data column sidecars were provided"
   277→    );
   278→  }
   279→
   280→  // Hash the first sidecar block header and compare the rest via (cheaper) equality
   281→  const firstSidecarBlockHeader = dataColumnSidecars[0].signedBlockHeader.message;
   282→  const firstBlockRoot = ssz.phase0.BeaconBlockHeader.hashTreeRoot(firstSidecarBlockHeader);
   283→  if (Buffer.compare(blockRoot, firstBlockRoot) !== 0) {
   284→    throw new DataColumnSidecarValidationError(
   285→      {
   286→        code: DataColumnSidecarErrorCode.INCORRECT_BLOCK,
   287→        slot: blockSlot,
   288→        columnIdx: 0,
   289→        expected: toRootHex(blockRoot),
   290→        actual: toRootHex(firstBlockRoot),
   291→      },
   292→      "DataColumnSidecar doesn't match corresponding block"
   293→    );
   294→  }
   295→
   296→  const commitments: Uint8Array[] = [];
   297→  const cellIndices: number[] = [];
   298→  const cells: Uint8Array[] = [];
   299→  const proofs: Uint8Array[] = [];
   300→  for (let i = 0; i < dataColumnSidecars.length; i++) {
   301→    const columnSidecar = dataColumnSidecars[i];
   302→
   303→    if (columnSidecar.index >= NUMBER_OF_COLUMNS) {
   304→      throw new DataColumnSidecarValidationError(
   305→        {
   306→          code: DataColumnSidecarErrorCode.INVALID_INDEX,
   307→          slot: blockSlot,
   308→          columnIdx: columnSidecar.index,
   309→        },
   310→        "DataColumnSidecar has invalid index"
   311→      );
   312→    }
   313→
   314→    if (columnSidecar.kzgCommitments.length !== blockBlobCount) {
   315→      throw new DataColumnSidecarValidationError({
   316→        code: DataColumnSidecarErrorCode.INCORRECT_KZG_COMMITMENTS_COUNT,
   317→        slot: blockSlot,
   318→        columnIdx: columnSidecar.index,
   319→        expected: blockBlobCount,
   320→        actual: columnSidecar.kzgCommitments.length,
   321→      });
   322→    }
   323→
   324→    if (columnSidecar.kzgProofs.length !== columnSidecar.kzgCommitments.length) {
   325→      throw new DataColumnSidecarValidationError({
   326→        code: DataColumnSidecarErrorCode.INCORRECT_KZG_PROOF_COUNT,
   327→        slot: blockSlot,
   328→        columnIdx: columnSidecar.index,
   329→        expected: columnSidecar.kzgCommitments.length,
   330→        actual: columnSidecar.kzgProofs.length,
   331→      });
   332→    }
   333→
   334→    if (!verifyDataColumnSidecarInclusionProof(columnSidecar)) {
   335→      throw new DataColumnSidecarValidationError(
   336→        {
   337→          code: DataColumnSidecarErrorCode.INCLUSION_PROOF_INVALID,
   338→          slot: blockSlot,
   339→          columnIdx: columnSidecar.index,
   340→        },
   341→        "DataColumnSidecar has invalid inclusion proof"
   342→      );
   343→    }
   344→
   345→    commitments.push(...columnSidecar.kzgCommitments);
   346→    cellIndices.push(...Array.from({length: columnSidecar.column.length}, () => columnSidecar.index));
   347→    cells.push(...columnSidecar.column);
   348→    proofs.push(...columnSidecar.kzgProofs);
   349→  }
   350→
   351→  let reason: string | undefined;
   352→  try {
   353→    const valid = await kzg.asyncVerifyCellKzgProofBatch(commitments, cellIndices, cells, proofs);
   354→    if (!valid) {
   355→      reason = "Invalid KZG proof batch";
   356→    }
   357→  } catch (e) {
   358→    reason = (e as Error).message;
   359→  }
   360→  if (reason !== undefined) {
   361→    throw new DataColumnSidecarValidationError(
   362→      {
   363→        code: DataColumnSidecarErrorCode.INVALID_KZG_PROOF_BATCH,
   364→        slot: blockSlot,
   365→        reason,
   366→      },
   367→      "DataColumnSidecar has invalid KZG proof batch"
   368→    );
   369→  }
   370→}
   371→
   372→/**
   373→ * SPEC FUNCTION
   374→ * https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/fulu/p2p-interface.md#compute_subnet_for_data_column_sidecar
   375→ */
   376→export function computeSubnetForDataColumnSidecar(
   377→  config: ChainConfig,
   378→  columnSidecar: fulu.DataColumnSidecar
   379→): SubnetID {
   380→  return columnSidecar.index % config.DATA_COLUMN_SIDECAR_SUBNET_COUNT;
   381→}
